package org.brightstats.data;

import java.nio.file.*;
import java.util.*;

public final class OrdinalDataChecks {
    static int checks;static void require(boolean value){checks++;if(!value)throw new AssertionError("Ordinal source/category contract");}static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid ordinal declaration accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{List<List<String>> rows=new ArrayList<>();for(int i=0;i<80;i++)rows.add(new ArrayList<>(List.of(i%2==0?(i%4==0?"1.0":"1"):"2",i/2%2==0?"low":"high",Integer.toString(i))));rows.get(0).set(0,"");rows.get(3).set(1,"");rows.get(7).set(2,"");var raw=new DataPreparation.Raw(List.of("A","B","Unused"),rows);var settings=new DataPreparation.Settings(',',DataPreparation.Decimal.DOT,"",DataPreparation.Missing.MEAN_REPLACEMENT);var definitions=List.of(new DataPreparation.Column("A",DataPreparation.Kind.NUMERIC),new DataPreparation.Column("B",DataPreparation.Kind.TEXT),new DataPreparation.Column("Unused",DataPreparation.Kind.NUMERIC));var levels=List.of(List.of("1","2"),List.of("high","low"));reject(()->OrdinalData.prepare(raw,settings,definitions,new OrdinalData.Specification(List.of("A","B"),levels,false)));var spec=new OrdinalData.Specification(List.of("A","B"),levels,true);var selected=OrdinalData.prepare(raw,settings,definitions,spec);require(selected.provenance().excludedRows()==2&&selected.codes().length==78);require(selected.provenance().sourceRows().getFirst()==2&&selected.provenance().sourceRows().contains(8));require(Arrays.equals(selected.codes()[0],new int[]{1,1}));require(OrdinalData.observedLevels(raw,settings,definitions,0).equals(List.of("1.0","2.0")));require(OrdinalData.prepare(raw,settings,definitions,spec).provenance().selectedDataSha256().equals(selected.provenance().selectedDataSha256()));reject(()->OrdinalData.prepare(raw,settings,definitions,new OrdinalData.Specification(List.of("A","B"),List.of(List.of("1","1.0"),List.of("high","low")),true)));var bad=rows.stream().map(ArrayList::new).map(v->(List<String>)v).toList();bad.get(10).set(0,"3");reject(()->OrdinalData.prepare(new DataPreparation.Raw(raw.headers(),bad),settings,definitions,spec));Thread.currentThread().interrupt();try{OrdinalData.prepare(raw,settings,definitions,spec);throw new AssertionError("Ordinal preparation cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}var commaRows=raw.rows().stream().map(ArrayList::new).map(v->(List<String>)v).toList();for(var row:commaRows)if(!row.get(0).isEmpty())row.set(0,row.get(0).startsWith("1")?"1,5":"2,0");var comma=new DataPreparation.Settings(',',DataPreparation.Decimal.COMMA,"",DataPreparation.Missing.MEAN_REPLACEMENT);var commaRaw=new DataPreparation.Raw(raw.headers(),commaRows);var inferred=OrdinalData.observedLevels(commaRaw,comma,definitions,0);require(inferred.equals(List.of("1,5","2,0")));require(Arrays.equals(OrdinalData.prepare(commaRaw,comma,definitions,new OrdinalData.Specification(List.of("A","B"),List.of(inferred,List.of("high","low")),true)).codes()[0],new int[]{1,1}));Path out=Path.of(args[0]);Files.createDirectories(out);Files.writeString(out.resolve("data-receipt.json"),"{\"state\":\"passed\",\"checks\":"+checks+"}");System.out.println("Ordinal source checks: "+checks);}
}
